use super::*;
fn NIO_step<'b,'i>(lane_data:&mut alloc::vec::Vec<core::cell::RefMut<'b,&'i mut [u8]>>,lane:&'b AccountInfo<'i>)->ProgramResult{
lane_data.push(lane.try_borrow_mut_data()?);
Ok(())}
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NIO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NIO_KMX::KMX_copy_from_slice)]
#[kani::stub(alloc::alloc::realloc,crate::NIO_KMX::KMX_realloc)]
#[kani::proof]
fn certificate(){use solana_program::{account_info::AccountInfo,pubkey::Pubkey,program_error::ProgramError};
let k0=Pubkey::new_from_array(kani::any()); let mut l0:u64=kani::any(); let mut d0=[kani::any::<u8>()]; let a0=AccountInfo::new(&k0,false,true,&mut l0,&mut d0,&k0,false,0);
let k1=Pubkey::new_from_array(kani::any()); let mut l1:u64=kani::any(); let mut d1=[kani::any::<u8>()]; let a1=AccountInfo::new(&k1,false,true,&mut l1,&mut d1,&k1,false,0);
let k2=Pubkey::new_from_array(kani::any()); let mut l2:u64=kani::any(); let mut d2=[kani::any::<u8>()]; let a2=AccountInfo::new(&k2,false,true,&mut l2,&mut d2,&k2,false,0);
let k3=Pubkey::new_from_array(kani::any()); let mut l3:u64=kani::any(); let mut d3=[kani::any::<u8>()]; let a3=AccountInfo::new(&k3,false,true,&mut l3,&mut d3,&k3,false,0);
let k4=Pubkey::new_from_array(kani::any()); let mut l4:u64=kani::any(); let mut d4=[kani::any::<u8>()]; let a4=AccountInfo::new(&k4,false,true,&mut l4,&mut d4,&k4,false,0);
let result=(||->ProgramResult{let _master_data=a4.try_borrow_mut_data()?;let mut lane_data=alloc::vec::Vec::with_capacity(8);
lane_data.push(a0.try_borrow_mut_data()?);
lane_data.push(a1.try_borrow_mut_data()?);
lane_data.push(a2.try_borrow_mut_data()?);
NIO_step(&mut lane_data,&a3)?;assert!(lane_data.len()==4);
assert!(a0.try_borrow_mut_data().is_err());
assert!(a1.try_borrow_mut_data().is_err());
assert!(a2.try_borrow_mut_data().is_err());
assert!(a3.try_borrow_mut_data().is_err());
assert!(a4.try_borrow_mut_data().is_err());
let unreleased=match lane_data.pop(){Some(g)=>g,None=>{assert!(false);return Ok(())}};core::mem::forget(unreleased);
Ok(())})();assert!(result==Ok(()));
assert!(a0.try_borrow_mut_data().is_ok());
assert!(a1.try_borrow_mut_data().is_ok());
assert!(a2.try_borrow_mut_data().is_ok());
assert!(a3.try_borrow_mut_data().is_ok());
assert!(a4.try_borrow_mut_data().is_ok());
}
